// And groups predicates with the AND operator between them.
func And(predicates ...predicate.CapturedMessage) predicate.CapturedMessage {
	return predicate.CapturedMessage(sql.AndPredicates(predicates...))
}

// Or groups predicates with the OR operator between them.
func Or(predicates ...predicate.CapturedMessage) predicate.CapturedMessage {
	return predicate.CapturedMessage(sql.OrPredicates(predicates...))
}

// Not applies the not operator on the given predicate.
func Not(p predicate.CapturedMessage) predicate.CapturedMessage {
	return predicate.CapturedMessage(sql.NotPredicates(p))
}
